package io.github.devpanel.support;

import org.springframework.context.annotation.Condition;
import org.springframework.context.annotation.ConditionContext;
import org.springframework.core.type.AnnotatedTypeMetadata;
import org.springframework.util.ClassUtils;

/**
 * The starter carries the panel twice: this copy for Spring Boot 2.7 ({@code javax.servlet})
 * and, generated by the build from the same sources, a copy in {@code io.github.devpanel.boot3}
 * for Spring Boot 3 ({@code jakarta.servlet}). Each entry point (auto-configuration, environment
 * post-processor, initializer, test listener) asks this class whether its copy is the one for
 * the running application; the other copy is never loaded.
 *
 * <p>Decided by the Spring Framework generation (6 has {@code org.springframework.aot}), not by
 * which servlet API happens to be on the classpath: old libraries drag {@code javax.servlet} into
 * Boot 3 applications and the other way round.
 */
public final class DevPanelFlavor implements Condition {

  /** The build sets this to true in the Boot 3 copy. */
  public static final boolean JAKARTA_COPY = false;

  private static final String SPRING_6_MARKER = "org.springframework.aot.AotDetector";

  public static boolean active(ClassLoader classLoader) {
    boolean spring6 = ClassUtils.isPresent(SPRING_6_MARKER,
        classLoader != null ? classLoader : DevPanelFlavor.class.getClassLoader());
    return spring6 == JAKARTA_COPY;
  }

  @Override
  public boolean matches(ConditionContext context, AnnotatedTypeMetadata metadata) {
    return active(context.getClassLoader());
  }
}
